// Package ops declares the full godot-ai-cli command surface: one OpSpec
// per plugin operation, generated by hand from the upstream tool→plugin
// command mapping (src/godot_ai/handlers/*.py) and kept honest by parity
// tests against the vendored plugin's register_lazy lines.
package ops

import (
	"fmt"
	"time"
)

// Timeout ladder, mirrored from upstream (protocol/timeouts.py, the
// plugin's deferred budgets in dispatcher.gd, and the per-call client
// timeouts in handlers/game.py).
const (
	// DefaultTimeout is the per-op default (the daemon's own default
	// execute budget is 8s too).
	DefaultTimeout = 8 * time.Second
	// TestRunTimeout mirrors TEST_RUN_TIMEOUT_SEC.
	TestRunTimeout = 300 * time.Second
	// ScreenshotTimeout mirrors the take_screenshot deferred budget.
	ScreenshotTimeout = 30 * time.Second
	// ScanTimeout mirrors the scan_filesystem deferred budget.
	ScanTimeout = 30 * time.Second
	// GameTimeout mirrors GAME_COMMAND_TIMEOUT_SEC (game_eval and
	// game_command share it).
	GameTimeout = 15 * time.Second
	// BatchTimeout is the batch_execute budget (rollback of a long batch
	// legitimately outlasts a single op).
	BatchTimeout = 30 * time.Second
	// InputSequenceTimeout mirrors INPUT_SEQUENCE_TIMEOUT_SEC: the
	// frame-timed sequence drives the game forward one frame per step.
	InputSequenceTimeout = 30 * time.Second
	// RecordTimeout mirrors RECORD_FRAMES_TIMEOUT_SEC plus margin: frame-aligned
	// burst capture takes one readback per game frame.
	RecordTimeout = 75 * time.Second
)

// Param kinds accepted by ParamSpec.Kind.
const (
	KindString = "string"
	KindInt    = "int"
	KindFloat  = "float"
	KindBool   = "bool"
	KindJSON   = "json" // raw JSON value (array, object, string, number)
)

// OpSpec declares one CLI leaf command bound to a plugin command.
type OpSpec struct {
	Domain        string        // CLI group, e.g. "node"
	Name          string        // CLI op name (kebab-case), e.g. "create"
	PluginCommand string        // wire command, e.g. "create_node"
	Summary       string        // English one-liner for help
	Timeout       time.Duration // per-op timeout from the upstream ladder
	Write         bool          // true → readiness gate (write:true on execute)
	Params        []ParamSpec   // declared flags
	// ResponseNote, when non-empty, is appended to the -h long help as a
	// "Response:" section documenting the payload fields (agents otherwise
	// discover response keys by trial and error).
	ResponseNote string
	// WrapOp, when non-empty, routes through a wrapper plugin command:
	// the wire params become {"op": WrapOp, "params": <collected>}.
	// Used by the game domain (everything goes through game_command).
	WrapOp string
}

// ParamSpec declares one typed flag on an op leaf command.
type ParamSpec struct {
	Flag     string // CLI flag name (kebab-case), e.g. "parent-path"
	Param    string // wire param key, e.g. "parent_path"
	Kind     string // string|int|float|bool|json
	Required bool
	Default  string // flag default (empty = kind zero value)
	Usage    string // English help text
}

// HandWiredLeaves documents the CLI leaves that are NOT OpSpec-backed
// because they talk to the daemon, not to a plugin command (or route
// through a dynamic command name, or — the image group — run fully local).
var HandWiredLeaves = []string{
	"session list",      // daemon-side: GET /godot-ai/cli/sessions
	"session activate",  // daemon-side: POST /godot-ai/cli/activate
	"custom list",       // daemon-side: custom-tool catalog cached from plugin events
	"custom invoke",     // dynamic plugin command custom_tool:<name>
	"call",              // escape hatch for arbitrary plugin commands
	"image palette",     // local: pure-Go texture palette analysis, no daemon
	"image probe",       // local: pure-Go pixel sampling, no daemon
	"image grid-detect", // local: pure-Go sprite-sheet grid detection, no daemon
}

// InternalOnlySpec documents a registered plugin command that is
// deliberately NOT exposed as a CLI subcommand.
type InternalOnlySpec struct {
	Command string
	Reason  string
}

// InternalOnly lists registered plugin commands with no CLI subcommand.
// The three client commands are registered in upstream but guarded off in
// this fork (ForkConfig.mcp_client_config_disabled); they are listed here
// so the parity test's set math stays exact.
var InternalOnly = []InternalOnlySpec{
	{Command: "configure_client", Reason: "unregistered in the godot-ai-cli fork — client configuration is a CLI/skill concern, not an editor operation"},
	{Command: "remove_client", Reason: "unregistered in the godot-ai-cli fork — client configuration is a CLI/skill concern, not an editor operation"},
	{Command: "check_client_status", Reason: "unregistered in the godot-ai-cli fork — client configuration is a CLI/skill concern, not an editor operation"},
}

