// All aggregates every domain's op table in the fixed domain order.
func All() []OpSpec {
	var out []OpSpec
	for _, domain := range domainOrder {
		out = append(out, domainOps(domain)...)
	}
	return out
}

// Domains returns the domain names in display order.
func Domains() []string {
	return append([]string(nil), domainOrder...)
}

// DomainSummary returns the parent-group help one-liner for a domain.
func DomainSummary(domain string) string {
	return domainSummaries[domain]
}

// domainOps resolves one domain's table.
func domainOps(domain string) []OpSpec {
	switch domain {
	case "editor":
		return editorOps()
	case "scene":
		return sceneOps()
	case "node":
		return nodeOps()
	case "script":
		return scriptOps()
	case "project":
		return projectOps()
	case "test":
		return testOps()
	case "animation":
		return animationOps()
	case "material":
		return materialOps()
	case "audio":
		return audioOps()
	case "particle":
		return particleOps()
	case "camera":
		return cameraOps()
	case "signal":
		return signalOps()
	case "input-map":
		return inputMapOps()
	case "game":
		return gameOps()
	case "autoload":
		return autoloadOps()
	case "filesystem":
		return filesystemOps()
	case "theme":
		return themeOps()
	case "ui":
		return uiOps()
	case "resource":
		return resourceOps()
	case "api":
		return apiOps()
	case "tilemap":
		return tilemapOps()
	case "tileset":
		return tilesetOps()
	case "gridmap":
		return gridmapOps()
	case "csg":
		return csgOps()
	case "batch":
		return batchOps()
	case "logs":
		return logsOps()
	default:
		return nil // session and custom are hand-wired in the CLI layer
	}
}

// Lookup finds one op by domain and name.
func Lookup(domain, name string) (OpSpec, bool) {
	for _, op := range All() {
		if op.Domain == domain && op.Name == name {
			return op, true
		}
	}
	return OpSpec{}, false
}

// ByDomain groups All() under its domain names (fixed order preserved).
func ByDomain() map[string][]OpSpec {
	out := map[string][]OpSpec{}
	for _, op := range All() {
		out[op.Domain] = append(out[op.Domain], op)
	}
	return out
}

// SortedDomainsWithOps returns domain names that have OpSpec-backed ops.
func SortedDomainsWithOps() []string {
	present := map[string]bool{}
	for _, op := range All() {
		present[op.Domain] = true
	}
	var out []string
	for _, d := range domainOrder {
		if present[d] {
			out = append(out, d)
		}
	}
	return out
}

// ps / pi / pf / pb / pj are ParamSpec constructors keeping the domain
// tables compact (string / int / float / bool / json kinds).

func ps(flag, param string, required bool, def, usage string) ParamSpec {
	return ParamSpec{Flag: flag, Param: param, Kind: KindString, Required: required, Default: def, Usage: usage}
}

func pi(flag, param string, required bool, def, usage string) ParamSpec {
	return ParamSpec{Flag: flag, Param: param, Kind: KindInt, Required: required, Default: def, Usage: usage}
}

func pf(flag, param string, required bool, def, usage string) ParamSpec {
	return ParamSpec{Flag: flag, Param: param, Kind: KindFloat, Required: required, Default: def, Usage: usage}
}

func pb(flag, param string, required bool, def, usage string) ParamSpec {
	return ParamSpec{Flag: flag, Param: param, Kind: KindBool, Required: required, Default: def, Usage: usage}
}

func pj(flag, param string, required bool, usage string) ParamSpec {
	return ParamSpec{Flag: flag, Param: param, Kind: KindJSON, Required: required, Usage: usage}
}

// Validate sanity-checks one spec; the convention tests run it over All().
func (op OpSpec) Validate() error {
	if op.Domain == "" || op.Name == "" || op.PluginCommand == "" || op.Summary == "" {
		return fmt.Errorf("op %s/%s: Domain, Name, PluginCommand, Summary are required", op.Domain, op.Name)
	}
	if op.Timeout < time.Second || op.Timeout > 600*time.Second {
		return fmt.Errorf("op %s/%s: timeout %s outside [1s, 600s]", op.Domain, op.Name, op.Timeout)
	}
	for _, p := range op.Params {
		switch p.Kind {
		case KindString, KindInt, KindFloat, KindBool, KindJSON:
		default:
			return fmt.Errorf("op %s/%s: param %s has invalid kind %q", op.Domain, op.Name, p.Flag, p.Kind)
		}
		if p.Flag == "" || p.Param == "" {
			return fmt.Errorf("op %s/%s: param with empty Flag or Param", op.Domain, op.Name)
		}
	}
	return nil
}
